const item = $input.first().json.body || $input.first().json;
const prompt = "You are an AI urban mobility optimization engine for Mana Community carpools.
You cluster commuters traveling to identical IT corridors, optimize the pickup order, calculate fuel cost splits, and compute CO2 reduction.
Analyze the input payload:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{
  "corridorName": "Outer Ring Road (Bellandur - Marathahalli)",
  "optimalRouteOrder": ["Flat A-204", "Flat B-502", "Flat C-101", "EcoWorld Tech Park"],
  "totalRouteKm": 14.8,
  "estimatedTimeMinutes": 38,
  "fairFuelSplitPerRiderInr": 65.0,
  "carbonEmissionSavedKg": 8.4,
  "pickupSchedule": [
    { "riderName": "Amit Roy", "flatNumber": "A-204", "pickupTime": "08:15 AM" },
    { "riderName": "Pooja Hegde", "flatNumber": "B-502", "pickupTime": "08:22 AM" }
  ],
  "routingRationale": "Single-direction departure from Main Gate avoids internal ring-road turnaround.",
  "auditTimestamp": "2026-11-21T08:30:00Z"
}";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

try {
  const raw = $input.first().json.candidates[0].content.parts[0].text;
  const parsed = JSON.parse(raw.trim());
  return [{ json: { success: true, aiGenerated: true, ...parsed } }];
} catch (e) {
  const orig = $('Prepare AI Prompt').first().json.originalInput;
  return [{ json: {
    success: true,
    aiGenerated: false,
    corridorName: orig.corridorName || "Outer Ring Road Tech Corridor",
    optimalRouteOrder: ["A-Block Pick Point", "B-Block Main Exit", "IT Park Destination"],
    totalRouteKm: 14.8,
    estimatedTimeMinutes: 35,
    fairFuelSplitPerRiderInr: 65.0,
    carbonEmissionSavedKg: 8.4,
    pickupSchedule: [
      { riderName: "Primary Pooler", flatNumber: "A-101", pickupTime: "08:20 AM" },
      { riderName: "Co-Pooler", flatNumber: "B-204", pickupTime: "08:28 AM" }
    ],
    routingRationale: "Sequential gate exit route calculated based on minimum detour distance.",
    auditTimestamp: new Date().toISOString()
  } }];
}
